public class DarkLaunchRouter {
    private final LegacyService legacyService;
    private final ModernService modernService;
    private final Executor asyncExecutor;
    private final MeterRegistry meterRegistry;

    public DarkLaunchRouter(LegacyService legacyService, ModernService modernService, Executor asyncExecutor, MeterRegistry meterRegistry) {
        this.legacyService = legacyService;
        this.modernService = modernService;
        this.asyncExecutor = asyncExecutor;
        this.meterRegistry = meterRegistry;
    }

    public Response executeRequest(Request request) {
        // Dark launch pattern: Asynchronously invoke the new service while returning legacy response
        CompletableFuture.runAsync(() -> {
            try {
                long start = System.nanoTime();
                modernService.process(request);
                meterRegistry.counter("dark.launch.success").increment();
            } catch (Exception e) {
                meterRegistry.counter("dark.launch.error").increment();
            }
        }, asyncExecutor);

        // Primary production path remains untouched by the experimental service failure
        return legacyService.process(request);
    }
}
